input:disabled + label {
	cursor: not-allowed
	}
	.ortasha{font-size:.9em;}
.Radio input,
.Checkbox input {
	display: none
	}
.Radio label,
.Checkbox label {
	padding: 0 14px 0 0;
	display: inline-block;
	cursor: pointer;
	position: relative
	}
.Radio label:before,
.Checkbox label:before {
	box-sizing: border-box;
	content: "";
	width: 16px;
	height: 16px;
	border-radius: 50%;
	border: 1px solid #999;
	margin: 0 3px;
	vertical-align: middle;
	display: inline-block;
	transition: 0.1S;
	}
.Radio label:hover:before,
.Checkbox label:hover:before {
	border-color: var(--green-logo);
	}
.Radio input:disabled + label:before,
.Checkbox input:disabled + label:before {
	background-color: #CCC;
	border-color: #999;
	opacity: 0.5;
	}
.Radio input:disabled + label,
.Checkbox input:disabled + label {
	opacity: 0.5;
	}
.Radio input:checked + label:before {
	border: 5px solid var(--green-logo);
	}
.Checkbox label:before {
	background: url(https://naryk.kz/img/tick_icon.svg) no-repeat center;
	background-size: 0;
	border-radius: 4px;
	transition: 0.3S;
	z-index:99999;
	}
.Checkbox input:checked + label:before {
	background-color: var(--green-logo);
	background-size: 16px;
	border-color: var(--green-logo);
	}
.HoverLabel label {
	display: block;
	border-radius: 4px;
	padding: 4px;
	}
.HoverLabel label:hover {
	background-color: rgba(208,229,193,.906);
	}
