<div class="col-lg-3 kase b_fon pos-sticky" id="calculator">
	<form id="kase_form">
		<h3 class="section-title-left mt-3"><a href="#">Биржа калькуляторы</a></h3>
		<div class="Label">Айлық табысыңыз (KZT)</div>
		<input type="number" class="mt-1 form-control" pattern="^\d*(\.\d{0,2})?$" name="salary" id="salary" min="10" max="100" />
		<div class="Label mt-2">Табысыңыздың қанша %-ын саласыз?</div>
		   <div class=" mt-2">
		   <input type="hidden" name="percent" value="0" id="percents_val">
<input type="button" class="mb-4 percents btn btn-send mb-1" value="10%" data-val="10">
<input type="button" class="mb-4 percents btn btn-send mb-1" value="20%" data-val="20">
<input type="button" class="mb-4 percents btn btn-send mb-1" value="30%" data-val="30">
<input type="button" class="mb-4 percents btn btn-send mb-1" value="40%" data-val="40">
<input type="button" class="mb-4 percents btn btn-send mb-1" value="50%" data-val="50">
			</div>
		<ul class="m-1em Checkbox HoverLabel">
			<li class="Dot Bold m-1em">Эмитенттер: <span class="birja_quny"> Акция құны (KZT)</span></li> 
			<li>
				<input class="stock-checkbox" id="safe21" name="stock_list[]" type="checkbox" value="KSPI" /><label for="safe21"><img src="https://naryk.kz/img/stock/KSPI.png" class="kase_logo"><span class="b_name">Kaspi.kz</span> <span class="birja" id="KSPI" > 53 883.90</span></label>
			</li>
			<li>
				<input class="stock-checkbox" id="safe22" name="stock_list[]" type="checkbox" value="KMGZ"/><label for="safe22"><img src="https://naryk.kz/img/stock/KMGZ.png" class="kase_logo"><span class="b_name">ҚазМұнайГаз</span> <span class="birja" id="KMGZ" > 13 906.00</span></label>
			</li>
			<li>
				<input class="stock-checkbox" id="safe23" name="stock_list[]" type="checkbox" value="HSBK" /><label for="safe23"><img src="https://naryk.kz/img/stock/HSBK.png" class="kase_logo"><span class="b_name">Halyk Bank</span> <span class="birja" id="HSBK" > 208.87</span></label>
			</li>
			<li>
				<input class="stock-checkbox" id="safe24" name="stock_list[]" type="checkbox" value="KCEL"  /><label for="safe24"><img src="https://naryk.kz/img/stock/KCEL.png" class="kase_logo"><span class="b_name">Kcell</span> <span class="birja" id="KCEL" > 3 264.28</span></label>
			</li>
			<li>
				<input class="stock-checkbox" id="safe25" name="stock_list[]" type="checkbox" value="KZAP"  /><label for="safe25"><img src="https://naryk.kz/img/stock/KZAP.ico" class="kase_logo"><span class="b_name">Kazatomprom</span> <span class="birja" id="KZAP" > 18 447.00</span></label>
			</li>
			<li class="mb-2"><em class="birja"> {{date('d.m.Y')}} күнгі баға </em></li>
		</ul>
		<div class="m-1em">
			<br>
		<button type="button" class="mb-3 b_knopka btn btn-send" onclick="calculate()">Есептеу</button>
		</div>
		<div id="birja_text" class="b_name b_natije" style="display:none">
			<p class="desc-text mb-2"></p>
			<div class="stock-result-list">
				<ul class="HoverLabel">
				</ul>
			</div>
			<div class="m-1em">
				<a href="https://tradernet.kz/?utm_campaign=global_mkting_pr&utm_medium=calculator&utm_source=naryk" class="mb-4 b_knopka btn btn-send mb-1">Акция алу</a>
		</div>
		</div>
	</div>
	
</div>
<script>
$(document).ready(function(){
	$.getJSON('https://apps.naryk.kz/get-sum', function(data) {
		$('#date').append(data.time);
		$('#KMGZ').append(data.kase.KMGZ.last);
		$('#HSBK').append(data.kase.HSBK.last);
		$('#KCEL').append(data.kase.KCEL.last);
		$('#KZAP').append(data.kase.KZAP.last);
		let kase_list = data["kase"];
		$('#kaspikz').append(kase_list.KSPI.last);
		if(Object.keys(kase_list).length > 0){
			jQuery.each(kase_list, function(i, val) {
				let img_html = "";
				if(val["status"] == "UP"){
					img_html = '<i class="fa fa-arrow-up b_icon b_icon_up" aria-hidden="true"></i>';
				}
				else if(val["status"] == "DOWN"){
					img_html = '<i class="fa fa-arrow-down b_icon b_icon_down" aria-hidden="true"></i>';
				}
				else{
					img_html = '<i class="fa fa-arrows-h b_icon b_icon_arrows" aria-hidden="true"></i>';
				}
				$("#" + i).html(val["last"] + " " + img_html);
				$("." + i).html(val["last"] + " " + img_html);
			});
		}
	});
	
	$(".percents").click(function(){
		$(".percents").removeClass("percents-active");
		$(this).addClass("percents-active");
		$("#percents_val").val($(this).data("val"));
		let sum_val_calculated = parseInt($("#salary").val())*parseInt($(this).val())/100;
		$("#sum_val_calculated").html(sum_val_calculated);
	});
	
	$("#salary").on("change", function(){
		let sum_val_calculated = parseInt($(".percents").val())*parseInt($(this).val())/100;
		$("#sum_val_calculated").html(sum_val_calculated);
	});
});


function calculate() {

	if($("#salary").val() < 1){
		alert("Табысыңызды енгізіңіз!");
		return false;
	}
	if($("#age_slider").val() < 1){
		alert("Процентті белгілеңіз!");
		return false;
	}
	if(document.querySelectorAll('input[name="stock_list[]"]:checked').length < 1){
		alert("Эмитентті белгілеңіз!");
		return false;
	}
	if($("#percents_val").val() < 1){
		alert("Процентті белгілеңіз!");
		return false;
	}
	
	$(".stock-result-list").find("ul").empty();
	$.ajax({
		type: 'POST',
		url: "https://apps.naryk.kz/calculate",
		data: $("#kase_form").serialize(),
		success: function(data){
			let count = Object.keys(data).length;
			$("#birja_text").find(".desc-text").html("Сіз табысыңыздың " + $("#percents_val").val() + "%-на осыншалықты акция ала аласыз:");
			let stock_result_list = "";
			if(Object.keys(data).length > 0){
				jQuery.each(data, function(i, val) {
				   
				  let stock_block = $("#" + i).closest("li").clone();
				  $(stock_block).find(".stock-checkbox").remove();
				  $(stock_block).find(".birja").html(val.toFixed(0));
				  $(".stock-result-list").find("ul").append(stock_block);	  
				});
			}
			
			document.getElementById('birja_text').style.display = "block";     
		},
		error: function(){
		   alert("Калькулятордан қате шықты!");
		}
	});
}
</script>
